import{_ as o,r as s,o as p,c as l,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Сортировка записей - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как сортировать и структурировать записи в списке.","frontmatter":{"subtitle":"Узнайте, как сортировать и структурировать записи в списке."},"headers":[{"level":2,"title":"Настройка поведения","slug":"настроика-поведения","link":"#настроика-поведения","children":[]},{"level":2,"title":"Поддерживаемые типы моделей","slug":"поддерживаемые-типы-моделеи","link":"#поддерживаемые-типы-моделеи","children":[{"level":3,"title":"Вложенное множество","slug":"вложенное-множество","link":"#вложенное-множество","children":[]},{"level":3,"title":"Простое дерево","slug":"простое-дерево","link":"#простое-дерево","children":[]},{"level":3,"title":"Сортируемая модель","slug":"сортируемая-модель","link":"#сортируемая-модель","children":[]}]},{"level":2,"title":"Сортировка связанных записей","slug":"сортировка-связанных-записеи","link":"#сортировка-связанных-записеи","children":[{"level":3,"title":"Трейт модели SortableRelation","slug":"треит-модели-sortablerelation","link":"#треит-модели-sortablerelation","children":[]}]}],"relativePath":"3.x/ru/extend/lists/structures.md","filePath":"3.x/ru/extend/lists/structures.md"}'),i={name:"3.x/ru/extend/lists/structures.md"};function d(u,a,k,h,g,m){const e=s("pre-heading"),t=s("post-heading");return p(),l("div",null,[n(e),a[0]||(a[0]=c("h1",null,"Сортировка записей",-1)),n(t),a[1]||(a[1]=r(`<p>October CMS предоставляет возможности для сортировки и переупорядочивания записей базы данных. Для поведений, поддерживающих структурированные списки, вы можете определить свойство <strong>structure</strong> для включения этой функции. Различные <a href="./../database/traits.html">трейты модели</a> используются для поддержки переупорядочивания, включая вложенные множества, простые деревья и сортируемые модели.</p><h2 id="настроика-поведения"><a href="#настроика-поведения" class="header-anchor">#</a> Настройка поведения</h2><p>Поведения панели управления <a href="./list-controller.html">Контроллер списков</a> и <a href="./../forms/form-controller.html">Контроллер связей</a> в настоящее время поддерживают возможность переупорядочивания записей с помощью свойства <strong>structure</strong> в соответствующем определении. При определении страница отображает список записей с маркером перетаскивания, позволяющим их сортировать и реструктурировать.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>

<span class="token comment"># ...</span>

<span class="token key atrule">structure</span><span class="token punctuation">:</span>
    <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">showSorting</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">maxDepth</span><span class="token punctuation">:</span> <span class="token number">2</span>
</code></pre></div><p>Ниже перечислены доступные свойства конфигурации.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>showTree</strong></td><td>отображает древовидную иерархию для записей родитель/потомок. По умолчанию: <code>true</code></td></tr><tr><td><strong>treeExpanded</strong></td><td>должны ли узлы дерева быть развёрнутыми по умолчанию. По умолчанию: <code>true</code></td></tr><tr><td><strong>showReorder</strong></td><td>отображает интерфейс для переупорядочивания записей. По умолчанию: <code>true</code></td></tr><tr><td><strong>showSorting</strong></td><td>позволяет сортировать записи, отключает структуру при сортировке. По умолчанию: <code>true</code></td></tr><tr><td><strong>maxDepth</strong></td><td>определяет максимальное количество уровней, допустимых для переупорядочивания. По умолчанию: <code>null</code></td></tr><tr><td><strong>dragRow</strong></td><td>позволяет перетаскивать всю строку в дополнение к маркеру переупорядочивания. По умолчанию: <code>true</code></td></tr><tr><td><strong>permissions</strong></td><td><a href="./../../extend/backend/permissions.html">разрешения</a>, которые должен иметь текущий пользователь панели управления для изменения структуры. Поддерживает как строку для одного разрешения, так и массив разрешений, из которых достаточно одного для предоставления доступа.</td></tr></tbody></table></div><h2 id="поддерживаемые-типы-моделеи"><a href="#поддерживаемые-типы-моделеи" class="header-anchor">#</a> Поддерживаемые типы моделей</h2><p>В зависимости от требований для управления вложенными и отсортированными записями может использоваться различный интерфейс модели. Поведение адаптируется в зависимости от того, какой трейт реализован.</p><h3 id="вложенное-множество"><a href="#вложенное-множество" class="header-anchor">#</a> Вложенное множество</h3><p>Используйте трейт <code>NestedTree</code>, когда необходима фиксированная структура. Это включает отношения родитель-потомок и когда записи должны отображаться в определённом порядке.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>NestedTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Подробнее о трейте <code>NestedTree</code> читайте в <a href="./../database/traits.html">документации по базам данных</a>.</p><h3 id="простое-дерево"><a href="#простое-дерево" class="header-anchor">#</a> Простое дерево</h3><p>Используйте трейт <code>SimpleTree</code>, когда необходимо базовое отношение родитель-потомок.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Category</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SimpleTree</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Подробнее о трейте <code>SimpleTree</code> читайте в <a href="./../database/traits.html">документации по базам данных</a>.</p><h3 id="сортируемая-модель"><a href="#сортируемая-модель" class="header-anchor">#</a> Сортируемая модель</h3><p>Используйте трейт <code>Sortable</code>, когда записи должны отображаться в определённом порядке.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Sortable</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Подробнее о трейте <code>Sortable</code> читайте в <a href="./../database/traits.html">документации по базам данных</a>.</p><h2 id="сортировка-связанных-записеи"><a href="#сортировка-связанных-записеи" class="header-anchor">#</a> Сортировка связанных записей</h2><p>Сортировка связанных записей возможна с помощью <a href="./../forms/relation-controller.html">Контроллера связей</a> с использованием свойства <strong>structure</strong>. Поддерживаемые типы связей перечислены ниже.</p><ul><li><a href="./../database/relations.html#relation-one-to-many">Has Many</a> использует трейт <code>Sortable</code> для связанной модели.</li><li><a href="./../database/relations.html#relation-many-to-many">Belongs To Many</a> использует трейт <code>SortableRelation</code> для родительской модели (см. ниже).</li></ul><h3 id="треит-модели-sortablerelation"><a href="#треит-модели-sortablerelation" class="header-anchor">#</a> Трейт модели SortableRelation</h3><p>Используйте трейт модели <code>SortableRelation</code>, когда записи должны сортироваться внутри сводной таблицы, например, для типа связи <a href="./../database/relations.html#many-to-many">Belongs To Many</a>. Этот трейт требует определения свойства <code>pivotSortable</code> в связи, где значение — это имя сортируемого столбца в сводной таблице.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>SortableRelation</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * @var array belongsToMany
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$belongsToMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name static-context">Role</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;table&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;users_roles&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;pivotSortable&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;sort_order&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Затем в вашей конфигурации связи вы должны включить свойство <code>showReorder</code> и отключить свойство <code>showTree</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token comment">#...</span>
    <span class="token key atrule">structure</span><span class="token punctuation">:</span>
        <span class="token key atrule">showReorder</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
        <span class="token key atrule">showTree</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div>`,28))])}const f=o(i,[["render",d]]);export{y as __pageData,f as default};
